import{_ as t,o as e,c as l,ag as a}from"./chunks/framework.KxDd3USm.js";const _=JSON.parse('{"title":"02.7 案例题专攻：数据库设计","description":"","frontmatter":{},"headers":[],"relativePath":"02-数据库系统/07-案例题专攻.md","filePath":"02-数据库系统/07-案例题专攻.md"}'),r={name:"02-数据库系统/07-案例题专攻.md"};function i(n,o,s,d,c,u){return e(),l("div",null,[...o[0]||(o[0]=[a('<h1 id="_02-7-案例题专攻-数据库设计" tabindex="-1">02.7 案例题专攻：数据库设计 <a class="header-anchor" href="#_02-7-案例题专攻-数据库设计" aria-label="Permalink to &quot;02.7 案例题专攻：数据库设计&quot;">​</a></h1><p>案例第 2 题一般是&quot;业务说明 + 不完整 E-R 图 + 关系模式 + SQL 填空&quot;，三小问固定套路：</p><h3 id="套路一-e-r-图补全——读句子找联系" tabindex="-1">套路一：E-R 图补全——读句子找联系 <a class="header-anchor" href="#套路一-e-r-图补全——读句子找联系" aria-label="Permalink to &quot;套路一：E-R 图补全——读句子找联系&quot;">​</a></h3><p>题干每个动词都暗示一条联系：&quot;学生<strong>选修</strong>课程&quot;&quot;教师<strong>讲授</strong>课程&quot;&quot;部门<strong>聘用</strong>员工&quot;。补空时：</p><ol><li>先数图中已有几实几联系，句子里的名词 = 实体、动词 = 联系；</li><li>联系类型用业务常识判：&quot;一个 X 对应几个 Y&quot;，两边都可多个才是 m:n；</li><li>m:n 联系上若有自己的属性（如&quot;成绩&quot;属于选课联系而非学生或课程），标在菱形上。</li></ol><h3 id="套路二-关系模式填空——主键外键往哪放" tabindex="-1">套路二：关系模式填空——主键外键往哪放 <a class="header-anchor" href="#套路二-关系模式填空——主键外键往哪放" aria-label="Permalink to &quot;套路二：关系模式填空——主键外键往哪放&quot;">​</a></h3><ol><li>每个实体一张表，主键 = 实体的码；</li><li>1:n 联系：把 1 端主键放进 <strong>n 端表</strong>作外键；</li><li>m:n 联系：单独建表，主键 = <strong>两端主键组合</strong>，联系的属性（成绩）也放这张表；</li><li>小问问&quot;XX 表的主键是什么&quot;：先想清它是实体表还是联系表，联系表的主键几乎总是组合键。</li></ol><h3 id="套路三-sql-填空——按-select-骨架对号入座" tabindex="-1">套路三：SQL 填空——按 SELECT 骨架对号入座 <a class="header-anchor" href="#套路三-sql-填空——按-select-骨架对号入座" aria-label="Permalink to &quot;套路三：SQL 填空——按 SELECT 骨架对号入座&quot;">​</a></h3><ol><li>空 FROM：看 SELECT 和 WHERE 里用了哪些列，缺哪张表补哪张，多表加 <code>JOIN ... ON 连接条件</code>；</li><li>空 WHERE：对应题干&quot;查询<strong>满足某条件</strong>的行&quot;，日期/字符串加引号；</li><li>空在聚合旁：&quot;每门课/每个部门的平均/最高/数量&quot;→ <code>GROUP BY</code> 分组列，条件带 AVG/MAX/COUNT 写 <code>HAVING</code>；</li><li>空在 CREATE TABLE：主键 <code>PRIMARY KEY(...)</code>、外键 <code>FOREIGN KEY(...) REFERENCES 表(列)</code>；</li><li>填完代入一条具体数据心里跑一遍（同第一课算法填空的自检法）。</li></ol><h3 id="套路四-题目要求-增加实体-时怎么改" tabindex="-1">套路四：题目要求“增加实体”时怎么改 <a class="header-anchor" href="#套路四-题目要求-增加实体-时怎么改" aria-label="Permalink to &quot;套路四：题目要求“增加实体”时怎么改&quot;">​</a></h3><p>这类小问不是只在图上多画一个矩形，而是要完成“业务句子 → E-R 图 → 关系模式”整条链。</p><p>例：在运动会业务中新增规则：“记录教练，教练属性包括教练编号、姓名；每名运动员恰由一名教练指导，一名教练可指导多名运动员。”</p><ol><li>名词“教练”有独立编号和属性 → 新增实体 <strong>教练</strong>；</li><li>动词“指导”连接教练与运动员；</li><li>一名教练对多名运动员、每名运动员只对一名教练 → 教练:运动员 = <strong>1:n</strong>；</li><li>转关系模式：新增 <code>教练(教练编号, 姓名)</code>；把 1 端的教练编号放到 n 端，因此运动员表改为 <code>运动员(运动员编号, 姓名, 团编号, 教练编号)</code>，教练编号是外键。</li></ol><p><strong>反例演示（易错）</strong>：把“指导”单独建成 <code>指导(教练编号, 运动员编号)</code> 并非一定语法错误，但对没有自身属性的 1:n 联系属于多余拆表；标准答法是把 1 端主键并入 n 端。若题干改成“运动员可由多名教练共同指导”，两边都可多，才应单独建立联系表。</p><p>范式小问的答题模板：<strong>“候选键为……；非主属性对候选键存在/不存在部分依赖，所以满足/不满足 2NF；存在/不存在传递依赖……，所以最高为……；建议分解为……，公共属性……能决定其中一表，故无损。”</strong> 按这条链写，结论和理由都有分。</p><hr>',16)])])}const h=t(r,[["render",i]]);export{_ as __pageData,h as default};
